-- REM-A4-PORTFOLIO-1 (2026-10-26, charter pillar autonomy; agent_issues 1000395, 100341, 99953, 2852, 1000194; the BP26 half of 2993 is migrations/2026-10-26-rem-a4-bp26-map.sql)
--
-- WHAT WAS MEASURED (qnfo-audit SELECT only, 2026-10-26 19:30Z)
--   1000395  nothing closes a PORTFOLIO-GAP ticket when its gap stops being detected: portfolio-autopilot closes the GAP when the TICKET closes (close-fixed-gaps), issue-meta-fold has no rule that reads portfolio_gaps.
--   100341   deploy-unrecorded voice-stt: portfolio_gaps rows for 2026-10-20 to 2026-10-26 are open and linked to the ticket, but portfolio-lifecycle v3 (SWEEP-FLEET-TASKS-C) reads action IN (deploy, deployed) and the
--            detector selects no live worker (voice-stt: deployment_history 1928 action deployed 2026-10-20, project_ledger W.voice-stt deployed). The contract is the time-gated probe of SWEEP-FLEET-TASKS-C: it answers
--            'pending' until a lifecycle tick on or after 2026-10-27 and last read 'deferred'.
--   99953    PORTFOLIO-GAP upgrade-compat qnfo-model-eval: live_date 2026-10-10, flips_count 0, trigger 5108 val 0 hit 0, no open upgrade-compat gap; the contract fails only on its third clause (no worker of the census
--            with a live date before 2026-10-10): q08-mind and voice-stt carry 2026-10-01 with flips_count 0, no Cloudflare default change lies between their date and today, so their date is no exposure and the clause fails the issue
--            for workers it is not about.
--   2852     capability_contract_conformance 0.9459: capability_audit_snapshot rows with empty capabilities[] and limitations[]: qnfo-agents (its /health declares neither) and voice-stt (no repository directory).
--   1000194  the three fixes (summary label, roadmap and goal counts in program_review_notes, daily scorecards) are live since qnfo-fleet-dashboard 1.59.1 and 1.59.2 (2026-10-25): portfolio_runs 37 reads
--            'constraint QNFO.OPS (program risk 666); portfolio risk 768' (run 32 had 'constraint QNFO.OPS risk 801'), program_review_notes carry roadmap_now and goals_adopted for 5 of 5 programs on 10-25 and 10-26,
--            program_scorecards exist for 10-25 and 10-26. The contract is the closure-observing template (born superseded): nothing could close the ticket.
--
-- WHAT THIS FILE DOES
--   1. Rule portfolio-gap-resolved joins the hourly workflow issue-meta-fold (inserted before the five settle statements): an open ticket titled 'PORTFOLIO-GAP <kind> <entity>' for deploy-unrecorded or project-stale-deploy,
--      whose newest portfolio_gaps row for that kind and entity is closed or resolved and older than the last day (the detector has not filed it since), and for which a successful deployment_history row of the worker
--      (action deploy or deployed; within 30 days for the stale-deploy kind) satisfies the detector, closes with 'moot:' evidence naming the gap row (day, status, resolved_at) and that deployment row (id, action, deployed_at).
--      It closes nothing today (the voice-stt rows are still open); it closes 100341 once the autopilot's close-unobserved has closed the rows, and any later ticket of the family.
--   2. The contracts of 100341, 99953 and 1000194 are rewritten to measure the defect (not a date, not another worker); the actions of those three and of 2852 stop saying VACUOUS-PROBE-V3-1. A repaired contract is left alone
--      (each statement is guarded by the exact shape it replaces).
--   3. One decision_log row.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE fleet_tasks SET definition = (SELECT b.definition FROM bak_20261026_rem_a4_portfolio_task b WHERE b.id = 'issue-meta-fold'), version = version + 1, updated_at = datetime('now') WHERE id = 'issue-meta-fold' AND EXISTS (SELECT 1 FROM bak_20261026_rem_a4_portfolio_task); UPDATE remediation_contracts SET verify_probe = (SELECT b.verify_probe FROM bak_20261026_rem_a4_portfolio_contract b WHERE b.class = remediation_contracts.class), action = (SELECT b.action FROM bak_20261026_rem_a4_portfolio_contract b WHERE b.class = remediation_contracts.class), status = (SELECT b.status FROM bak_20261026_rem_a4_portfolio_contract b WHERE b.class = remediation_contracts.class), verify_transport = (SELECT b.verify_transport FROM bak_20261026_rem_a4_portfolio_contract b WHERE b.class = remediation_contracts.class), module = (SELECT b.module FROM bak_20261026_rem_a4_portfolio_contract b WHERE b.class = remediation_contracts.class), last_verdict = (SELECT b.last_verdict FROM bak_20261026_rem_a4_portfolio_contract b WHERE b.class = remediation_contracts.class), attempts = (SELECT b.attempts FROM bak_20261026_rem_a4_portfolio_contract b WHERE b.class = remediation_contracts.class), next_due_at = (SELECT b.next_due_at FROM bak_20261026_rem_a4_portfolio_contract b WHERE b.class = remediation_contracts.class) WHERE class IN (SELECT class FROM bak_20261026_rem_a4_portfolio_contract)

CREATE TABLE IF NOT EXISTS bak_20261026_rem_a4_portfolio_task AS SELECT id, version, definition, updated_at FROM fleet_tasks WHERE id = 'issue-meta-fold';
CREATE TABLE IF NOT EXISTS bak_20261026_rem_a4_portfolio_contract AS SELECT * FROM remediation_contracts WHERE class IN ('issue-100341', 'issue-99953', 'issue-2852', 'issue-1000194');

-- 1. the rule, inserted in front of the first settle statement (the anchor occurs once; a definition that already holds the rule, or does not hold the anchor exactly once, is left alone)
WITH a(x) AS (SELECT '{"type":"sql","db":"AUDIT","sql":"UPDATE remediation_contracts SET status = ''superseded'', last_verdict = ''superseded:closure-superseded (ISSUE-HYGIENE-1)''')
UPDATE fleet_tasks
   SET definition = replace(definition, (SELECT x FROM a), json_object('type', 'sql', 'db', 'AUDIT', 'sql', 'INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, ''portfolio-gap-resolved'', NULL, ''moot: the gap this issue reports is no longer detected: the newest portfolio_gaps row for '' || g.kind || '' '' || g.entity || '' is day '' || g.day || '' (status '' || g.status || '', resolved_at '' || COALESCE(g.resolved_at, ''?'') || '') and no row of that kind and entity is filed on or after '' || date(''now'', ''-1 day'') || ''; deployment_history row '' || d.id || '' (action '' || d.action || '', deployed_at '' || COALESCE(d.deployed_at, ''?'') || '') satisfies the detector. PORTFOLIO-GAP-RESOLVED-1 ISSUE-HYGIENE-1 '' || strftime(''%Y-%m-%d'', ''now''), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM agent_issues m JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = ''issue-'' || m.id JOIN portfolio_gaps g ON m.title = ''PORTFOLIO-GAP '' || g.kind || '' '' || g.entity JOIN deployment_history d ON d.id = (SELECT MAX(d2.id) FROM deployment_history d2 WHERE d2.resource_name = CASE WHEN g.kind = ''project-stale-deploy'' THEN substr(g.entity, 3) ELSE g.entity END AND d2.action IN (''deploy'', ''deployed'') AND COALESCE(d2.status, ''success'') = ''success'' AND (g.kind = ''deploy-unrecorded'' OR replace(substr(COALESCE(d2.deployed_at, ''''), 1, 19), ''T'', '' '') >= datetime(''now'', ''-30 days''))) WHERE m.status = ''open'' AND (m.title LIKE ''PORTFOLIO-GAP deploy-unrecorded %'' OR m.title LIKE ''PORTFOLIO-GAP project-stale-deploy %'') AND g.kind IN (''deploy-unrecorded'', ''project-stale-deploy'') AND g.status IN (''closed'', ''resolved'') AND g.day = (SELECT MAX(g2.day) FROM portfolio_gaps g2 WHERE g2.kind = g.kind AND g2.entity = g.entity) AND g.day < date(''now'', ''-1 day'') AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0) ORDER BY m.id LIMIT 200') || ',' || (SELECT x FROM a)),
       version = version + 1, updated_at = datetime('now')
 WHERE id = 'issue-meta-fold' AND json_valid(definition) AND instr(definition, 'portfolio-gap-resolved') = 0
   AND length(definition) - length(replace(definition, (SELECT x FROM a), '')) = length((SELECT x FROM a));

-- 2. the contracts
UPDATE remediation_contracts SET status = 'active', verify_transport = 'd1-query', module = 'rem-a4-portfolio', verify_probe = 'SELECT ''0'' AS expected, CASE WHEN instr((SELECT definition FROM fleet_tasks WHERE id = ''portfolio-lifecycle''), ''dh.resource_name=s.service AND dh.action IN (''''deploy'''',''''deployed'''')'') = 0 THEN ''the deploy-unrecorded detector of portfolio-lifecycle does not read reconciled deployments'' ELSE CAST((SELECT COUNT(*) FROM service_registry s WHERE s.service = ''voice-stt'' AND s.kind = ''worker'' AND s.state = ''live'' AND NOT EXISTS (SELECT 1 FROM deployment_history dh WHERE dh.resource_name = s.service AND dh.action IN (''deploy'', ''deployed'') AND COALESCE(dh.status, ''success'') = ''success'')) AS TEXT) END AS observed', action = 'MEASURES the defect: the deploy-unrecorded gap for voice-stt was filed every day because the detector counted only deployment_history.action = deploy, while the live deployment is recorded by deployment-ledger-reconcile as action deployed. Reads 0 when the live portfolio-lifecycle detector reads action IN (deploy, deployed) and selects no live worker without a successful deploy row (voice-stt has deployment_history 1928, project_ledger W.voice-stt deployed 2026-10-20). A reverted detector or a removed deployment row makes it read a non-zero text. REM-A4-PORTFOLIO-1 replaced the time-gated probe (it could not read before 2026-10-27).',
  last_verdict = NULL, attempts = 0, next_due_at = datetime('now')
WHERE class = 'issue-100341' AND instr(verify_probe, 'pending: no portfolio-lifecycle tick has run') > 0;
UPDATE remediation_contracts SET status = 'active', verify_transport = 'd1-query', module = 'rem-a4-portfolio', verify_probe = 'SELECT ''1'' AS expected, CASE WHEN (SELECT live_date FROM worker_compat_state WHERE worker = ''qnfo-model-eval'' ORDER BY checked_at DESC LIMIT 1) >= ''2026-10-10'' AND (SELECT COALESCE(flips_count, 0) FROM worker_compat_state WHERE worker = ''qnfo-model-eval'' ORDER BY checked_at DESC LIMIT 1) = 0 AND NOT EXISTS (SELECT 1 FROM portfolio_gaps WHERE kind = ''upgrade-compat'' AND entity = ''qnfo-model-eval'' AND status = ''open'') AND (SELECT hit FROM v_metric_trigger_state WHERE id = 5108) = 0 THEN ''1'' ELSE ''0'' END AS observed', action = 'MEASURES the defect of this issue (qnfo-model-eval behind the compatibility default): qnfo-model-eval runs compatibility date 2026-10-10 or later, no Cloudflare default change lies between that date and today (worker_compat_state.flips_count = 0), no upgrade-compat gap is open for it and the compat metric trigger 5108 is not in breach. REM-A4-PORTFOLIO-1 dropped the clause ''no worker in the census has a live date before 2026-10-10'': q08-mind and voice-stt carry 2026-10-01 with flips_count 0, so their date is not an exposure and the clause failed this issue for workers it is not about.',
  last_verdict = NULL, attempts = 0, next_due_at = datetime('now')
WHERE class = 'issue-99953' AND instr(verify_probe, 'live_date<''2026-10-10''') > 0;
UPDATE remediation_contracts SET status = 'active', verify_transport = 'd1-query', module = 'rem-a4-portfolio', verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM portfolio_runs WHERE kind = ''weekly-strategic'' AND run_date = (SELECT MAX(run_date) FROM portfolio_runs WHERE kind = ''weekly-strategic'') AND instr(summary, ''(program risk '') > 0 AND instr(summary, ''); portfolio risk '') > 0) THEN ''the newest weekly review summary does not label the constraint program risk and the portfolio risk separately'' WHEN EXISTS (SELECT 1 FROM program_review_notes WHERE day = (SELECT MAX(day) FROM program_review_notes) AND (roadmap_now IS NULL OR goals_adopted IS NULL)) THEN ''the newest program_review_notes carry no roadmap or goal counts'' WHEN COALESCE((SELECT MAX(day) FROM program_scorecards), ''1970-01-01'') < date(''now'', ''-1 day'') THEN ''the program scorecards are more than a day old: the daily run does not compute them'' ELSE ''ok'' END AS observed', action = 'MEASURES the three fixes of PORTFOLIO-STRATEGIC-2 in the data they produce (qnfo-fleet-dashboard 1.59.1 and 1.59.2, live): (a) the newest weekly-strategic summary reads ''constraint <program> (program risk N); portfolio risk M'' (run 37 of 2026-10-26: program risk 666, portfolio risk 768; run 32 had printed 801 beside the program); (b) the newest program_review_notes rows carry roadmap_now and goals_adopted (5 of 5 programs on 2026-10-25 and 2026-10-26); (c) program_scorecards are computed daily by portfolioDailyRun (rows for 2026-10-25 and 2026-10-26). REM-A4-PORTFOLIO-1 replaced the closure-observing template (it could not pass before the close it blocks).',
  last_verdict = NULL, attempts = 0, next_due_at = datetime('now')
WHERE class = 'issue-1000194' AND status = 'superseded' AND instr(action, 'VACUOUS-PROBE-V3-1') = 1;
UPDATE remediation_contracts SET module = 'rem-a4-portfolio', action = 'MEASURES the defect: capability_contract_conformance (metric_history, newest value) must read 1 or more. The metric counts the workers whose capabilities[] and limitations[] are both non-empty in a capability_audit_snapshot row under 26 hours old. Read 2026-10-26 19:30Z: 0.9459; the non-conforming rows are qnfo-agents (its /health declares neither array) and voice-stt (no repository directory, no version). OBJECTIVE-CONSTRAINTS-1 closes the issue itself on the first hourly tick that measures it within target.'
WHERE class = 'issue-2852' AND instr(action, 'VACUOUS-PROBE-V3-1') = 1;

-- 3. the decision
INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'rem-a4-portfolio', 'a PORTFOLIO-GAP ticket whose gap the detector no longer files has nothing left to do, and a closing probe must read the defect it names (the detector or the entity), not a calendar date or an unrelated worker', 'REM-A4-PORTFOLIO-1: rule portfolio-gap-resolved joins the hourly workflow issue-meta-fold; contracts of 100341, 99953 and 1000194 measure their defect; actions of 100341, 99953, 2852 and 1000194 stop saying VACUOUS-PROBE-V3-1', 'portfolio_gaps newest voice-stt deploy-unrecorded row day 2026-10-26 open (issue 100341) while portfolio-lifecycle v3 (SWEEP-FLEET-TASKS-C) reads action IN (deploy, deployed) and the detector selects 0 live workers; worker_compat_state qnfo-model-eval live_date 2026-10-10, flips_count 0, trigger 5108 val 0 hit 0, with q08-mind and voice-stt at 2026-10-01 and flips_count 0; portfolio_runs 37 summary ''constraint QNFO.OPS (program risk 666); portfolio risk 768'', program_review_notes 5 of 5 with roadmap_now and goals_adopted, program_scorecards 2026-10-26; capability_audit_snapshot qnfo-agents and voice-stt empty arrays; offline suite migrations/rem-a4-portfolio.test.mjs', 'applied by migration', 'one extra statement on the hourly workflow issue-meta-fold (closes nothing today: no open PORTFOLIO-GAP ticket has a closed newest gap row older than a day); five contract rows rewritten', 'the Rollback line restores the saved workflow definition and the saved contract rows', 'a PORTFOLIO-GAP ticket for deploy-unrecorded or project-stale-deploy closes with evidence when its gap stops being detected', '100341 and 1000194 close on their next passing verification; 99953 after two consecutive passes (it was reopened once); 1000395 closes once 100341 is closed; 2852 closes at the objective tick when qnfo-agents and voice-stt declare their arrays', 'none', 'd1:qnfo-audit portfolio_gaps, deployment_history, service_registry, worker_compat_state, v_metric_trigger_state, portfolio_runs, program_review_notes, program_scorecards, capability_audit_snapshot, fleet_tasks (SELECT only); offline node:sqlite replay of issue-hygiene-1..3 plus this file'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE instr(action, 'REM-A4-PORTFOLIO-1:') = 1);
